sys_script_include.script:
var askforupdate = Class.create();
askforupdate.prototype = Object.extendsObject(global.AbstractAjaxProcessor, {
	getItemInfo: function(){
		var sysId = this.getParameter('sysparm_sys_id');
		var reqItem = new GlideRecord('sc_req_item');
		reqItem.get(sysId);
		reqItem.stage = 'Approval';
		gs.error('reqItem.request.number:' + reqItem.request.number);
		var number = reqItem.request.number;
		reqItem.update();
		var request = new GlideRecord('sc_request');
		request.get('number', number);
		gs.error('request.number:' + number);
		//request.stage = 'Fulfillment';
		gs.error('request.stage:' + request.stage);
		request.stage = 'Fulfillment';
		request.assigned_to = 'Abraham Lincoln';

		var updateResult = request.update();
		//gs.error('request.update:' + updateResult);

		var task = new GlideRecord('sc_task');
		task.initialize();
		task.short_description = 'Need More Info for your Computer Request.';
		task.description = 'The request need more info. Please update the details in below link:  ' + 'https://dev277680.service-now.com/sp?id=sc_cat_item&sys_id=6af61df7c32d221038ffb813e401316a&catitem_id=' + sysId;
		task.assigned_to = reqItem.opened_by;
		task.task_type = 'task';
		task.insert();
		return true;
	},
    type: 'askforupdate'
});
